140	  // the direction that resumes a branch which may have been delivered; the other
141	  // loses one that has not been.
142	  if (!tip) return false;
143	  const prs = gh("api", `repos/${repo}/pulls?state=all&per_page=100&head=${owner}:${branch}`);
144	  if (prs.code) {
145	    log(`WARN could not read pull requests for ${branch}; treating it as unmerged`);
146	    return false;
147	  }
148	  try {
149	    const parsed = JSON.parse(prs.stdout || "[]") as {
150	      merged_at?: string | null;
151	      head?: { sha?: string };
152	    }[];
153	    return parsed.some((pr) => Boolean(pr.merged_at) && pr.head?.sha === tip);
154	  } catch {
155	    log(`WARN pull request list for ${branch} was not valid JSON`);
156	    return false;
157	  }
